__mod["model.draft"] = function(...)
-- Analysis of the "Enter code" form: format, line errors, name check (pure Lua).
local formats = require("model.formats")
local library = require("model.library")
local util = require("model.util")

local D = {}

--- draft = { name, fmt ("auto"|format id), code, editing (entry id|nil) }
-- ctx = { system, list (existing entries), supported(format) -> boolean }
-- Returns { fmt, detected, chk, blank, name_state ("empty"|"taken"|"ok"), ready, unsupported }
function D.analyze(draft, ctx)
  local res = { blank = util.trim(draft.code or "") == "" }
  res.detected = formats.detect(draft.code or "", ctx.system)
  if draft.fmt == "auto" then res.fmt = res.detected else res.fmt = draft.fmt end
  local name = util.trim(draft.name or "")
  if name == "" then
    res.name_state = "empty"
  elseif library.name_taken(ctx.list, name, draft.editing) then
    res.name_state = "taken"
  else
    res.name_state = "ok"
  end
  if res.fmt and not res.blank then
    res.chk = formats.check(draft.code, res.fmt, ctx.system)
    res.unsupported = not ctx.supported(res.fmt)
  end
  res.ready = res.name_state == "ok" and res.chk ~= nil and #res.chk.errors == 0 and res.chk.count > 0
  return res
end

return D

end
__mod["model.formats"] = function(...)
-- Cheat code formats: shapes, validation, detection and normalizing (pure Lua).
--
-- Format ids are the ones of `uz.cheats.formats()`:
--   raw        AAAAAAAA VV            address (8 hex) and one byte (2 hex)
--   gsa        XXXXXXXX YYYYYYYY      GameShark Advance, 8 + 8 hex (or 12 hex in one group)
--   cb         XXXXXXXX YYYY          CodeBreaker, 8 + 4 hex
--   ar_gba     XXXXXXXX YYYYYYYY      Action Replay GBA, 8 + 8 hex (or 12 hex in one group)
--   ar_ds      XXXXXXXX YYYYYYYY      Action Replay DS, 8 + 8 hex
--   gateway    XXXXXXXX YYYYYYYY      Gateway (3DS), 8 + 8 hex
--   game_genie XXX-XXX[-XXX]          Game Genie (Game Boy), hex groups of 3
local util = require("model.util")

local F = {}

F.order = { "gsa", "cb", "ar_gba", "ar_ds", "game_genie", "gateway", "raw" }
F.tags = { gsa = "GSA", cb = "CB", ar_gba = "AR GBA", ar_ds = "AR DS", game_genie = "GG", gateway = "GATEWAY", raw = "RAW" }
-- Group sizes of the accepted line shapes (alternatives per format).
local SHAPES = {
  raw = { { 8, 2 } },
  gsa = { { 8, 8 }, { 12 } },
  cb = { { 8, 4 } },
  ar_gba = { { 8, 8 }, { 12 } },
  ar_ds = { { 8, 8 } },
  gateway = { { 8, 8 } },
  game_genie = { { 3, 3 }, { 3, 3, 3 } },
}
-- Formats that make sense per system, in detection priority.
F.by_system = {
  gb = { "game_genie", "raw" },
  gbc = { "game_genie", "raw" },
  gba = { "gsa", "cb", "ar_gba", "raw" },
  nds = { "ar_ds", "raw" },
  ["3ds"] = { "gateway", "raw" },
}
local MAX_LINES = 64

function F.known(format) return SHAPES[format] ~= nil end

--- Plausible formats for a system (all formats for an unknown one).
function F.for_system(system)
  return F.by_system[tostring(system or ""):lower()] or F.order
end

--- Short text of the shape, e.g. "8 + 8" (Game Genie: "3-3 or 3-3-3").
function F.shape_text(format)
  local alts = {}
  for _, g in ipairs(SHAPES[format] or {}) do
    local parts = {}
    for i, n in ipairs(g) do parts[i] = tostring(n) end
    alts[#alts + 1] = table.concat(parts, format == "game_genie" and "-" or " + ")
  end
  if format == "game_genie" then return table.concat(alts, " or ") end
  return alts[1] or ""
end

local function err(key, vars) return nil, key, vars end

--- Validates one code line for a format. Returns true or nil, error key, vars.
function F.validate_line(format, line)
  local shapes = SHAPES[format]
  if not shapes then return err("err_format") end
  line = util.trim(line)
  if line == "" then return err("err_empty") end
  local tag = F.tags[format]
  local vars = { tag = tag, shape = F.shape_text(format) }
  -- illegal characters first: the first one that is not a hex digit
  local allowed = format == "game_genie" and "^[%x%s%-]*$" or "^[%x%s]*$"
  if not line:match(allowed) then
    local bad = line:match(format == "game_genie" and "[^%x%s%-]" or "[^%x%s]")
    vars.char = bad
    return err("err_not_hex", vars)
  end
  local groups = {}
  if format == "game_genie" then
    for g in line:gmatch("[^%-%s]+") do groups[#groups + 1] = g end
    if line:find("%s") then return err("err_shape", vars) end
  else
    for g in line:gmatch("%S+") do groups[#groups + 1] = g end
  end
  for _, shape in ipairs(shapes) do
    if #shape == #groups then
      local ok = true
      for i, n in ipairs(shape) do if #groups[i] ~= n then ok = false end end
      if ok then return true end
    end
  end
  -- explain against the first shape with the same group count, else the primary one
  local want
  for _, shape in ipairs(shapes) do if #shape == #groups then want = shape; break end end
  if not want then
    if #groups == 1 and #shapes[1] == 2 and format ~= "game_genie" then
      vars.n = #groups[1]
      return err("err_one_group", vars)
    end
    vars.n = #groups
    return err("err_group_count", vars)
  end
  for i, n in ipairs(want) do
    if #groups[i] ~= n then
      vars.n, vars.want = #groups[i], n
      if format == "game_genie" then
        vars.pos = i
        return err("err_gg_group", vars)
      end
      return err(i == 1 and (#want == 1 and "err_digits_total" or "err_digits_before") or "err_digits_after", vars)
    end
  end
  return err("err_shape", vars)
end

--- Normalized code line: upper case, single spaces (Game Genie: dashes).
function F.normalize_line(format, line)
  line = util.trim(line):upper()
  if format == "game_genie" then
    local g = {}
    for x in line:gmatch("[^%-%s]+") do g[#g + 1] = x end
    return table.concat(g, "-")
  end
  return (line:gsub("%s+", " "))
end

--- True when the line is a valid code of any format.
function F.is_code_line(line)
  for _, f in ipairs(F.order) do
    if F.validate_line(f, line) then return true end
  end
  return false
end

--- Non-empty lines with their original line numbers: { {n=, text=}, ... }.
function F.code_lines(text)
  local out = {}
  for i, l in ipairs(util.lines(text)) do
    if util.trim(l) ~= "" then out[#out + 1] = { n = i, text = l } end
  end
  return out
end

local function all_valid(format, lines)
  for _, l in ipairs(lines) do
    if not F.validate_line(format, l.text) then return false end
  end
  return #lines > 0
end

--- Formats under which every line is valid, most likely first (system priority, then the rest).
function F.candidates(text, system)
  local lines = F.code_lines(text)
  local out, seen = {}, {}
  for _, f in ipairs(F.for_system(system)) do
    if all_valid(f, lines) then out[#out + 1] = f; seen[f] = true end
  end
  for _, f in ipairs(F.order) do
    if not seen[f] and all_valid(f, lines) then out[#out + 1] = f end
  end
  return out
end

--- Detects the format of a code text. Returns the format id or nil. Formats of the system win.
function F.detect(text, system)
  local c = F.candidates(text, system)
  return c[1]
end

--- Checks a code text against a chosen format.
-- Returns { lines = {normalized...}, errors = { {n=, key=, vars=} }, count = n, other = format|nil }
-- `other` is a different format under which every line would be valid (the "wrong format" hint).
function F.check(text, format, system)
  local lines = F.code_lines(text)
  local res = { lines = {}, errors = {}, count = #lines }
  if #lines > MAX_LINES then
    res.errors[1] = { n = lines[MAX_LINES + 1].n, key = "err_too_many_lines", vars = { max = MAX_LINES } }
    return res
  end
  for _, l in ipairs(lines) do
    local ok, key, vars = F.validate_line(format, l.text)
    if ok then
      res.lines[#res.lines + 1] = F.normalize_line(format, l.text)
    else
      res.errors[#res.errors + 1] = { n = l.n, key = key, vars = vars }
    end
  end
  if #res.errors > 0 then
    local c = F.candidates(text, system)
    for _, f in ipairs(c) do
      if f ~= format then res.other = f; break end
    end
  end
  return res
end

return F

end
__mod["model.importer"] = function(...)
-- Reads cheat files: RetroArch .cht and text files (Gateway `[Name]` blocks, plain AR/GS text).
-- Pure Lua. parse(content, system) -> { kind = "cht"|"txt", cheats = { {name=, lines=, code=, format=} }, bad = n,
-- dropped = n } (`dropped`: entries with a name but no readable code, left out of `cheats`)
local util = require("model.util")
local formats = require("model.formats")

local I = {}

local MAX_NAME = 60
local MAX_CHEATS = 1000

local function clean_name(s, fallback)
  s = util.trim((s or ""):gsub("%c+", " "))
  if s == "" then s = fallback end
  return util.clip(s, MAX_NAME)
end

-- Finishes one raw cheat: detects the format and normalizes the lines.
local function finish(raw_lines, name, system, index)
  local text = table.concat(raw_lines, "\n")
  local fmt = formats.detect(text, system)
  local entry = { name = clean_name(name, "Cheat " .. index), format = fmt }
  if fmt then
    local chk = formats.check(text, fmt, system)
    entry.lines = chk.lines
    entry.code = table.concat(chk.lines, "\n")
    if #chk.errors > 0 then entry.format, entry.lines, entry.code = nil, nil, nil end
  end
  if not entry.format then
    entry.lines, entry.code = raw_lines, text
    entry.invalid = true
  end
  return entry
end

local function unquote(v)
  v = util.trim(v)
  local q = v:match('^"(.*)"$')
  return q or v
end

function I.parse_cht(content, system)
  local by_index, max_index = {}, 0
  for _, line in ipairs(util.lines(content)) do
    local n, field, value = line:match("^%s*cheat(%d+)_([%w_]+)%s*=%s*(.-)%s*$")
    if n then
      n = tonumber(n)
      if n < MAX_CHEATS then
        by_index[n] = by_index[n] or {}
        by_index[n][field] = unquote(value)
        if n > max_index then max_index = n end
      end
    end
  end
  local out, bad, dropped = {}, 0, 0
  for n = 0, max_index do
    local c = by_index[n]
    if c and (c.code or c.desc) and not (c.code and util.trim(c.code) ~= "") then dropped = dropped + 1 end
    if c and (c.code or c.desc) and c.code and util.trim(c.code) ~= "" then
      local raw = {}
      for part in (c.code:gsub("[%+\n]", "\n")):gmatch("[^\n]+") do
        if util.trim(part) ~= "" then raw[#raw + 1] = util.trim(part) end
      end
      local e = finish(raw, c.desc, system, #out + 1)
      e.enable = c.enable == "true"
      if e.invalid then bad = bad + 1 end
      out[#out + 1] = e
    end
  end
  return { kind = "cht", cheats = out, bad = bad, dropped = dropped }
end

--- A line of hex digits that is not a valid code (a broken code, not a name).
function I.looks_like_code(line)
  if not line:match("^[%x%s%-]+$") or not line:find("%d") then return false end
  return #line:gsub("[^%x]", "") >= 5
end

function I.parse_txt(content, system)
  local blocks, cur, dropped = {}, nil, 0
  local function flush()
    if cur and #cur.lines > 0 then blocks[#blocks + 1] = cur
    elseif cur then dropped = dropped + 1 end -- a name or header without a readable code
    cur = nil
  end
  for _, raw in ipairs(util.lines(content)) do
    local line = util.trim(raw)
    local header = line:match("^%[(.+)%]$")
    if line == "" then
      -- a blank line ends a block that already has code
      if cur and #cur.lines > 0 then flush() end
    elseif line:match("^[#;]") or line:match("^//") then
      -- comment
    elseif header then
      flush()
      cur = { name = header, lines = {} }
    elseif formats.is_code_line(line) or I.looks_like_code(line) then
      cur = cur or { name = nil, lines = {} }
      cur.lines[#cur.lines + 1] = line
    else
      -- a name line: starts a new cheat (or renames one that has no code yet)
      if cur and #cur.lines == 0 then
        cur.name = line
      else
        flush()
        cur = { name = line, lines = {} }
      end
    end
  end
  flush()
  local out, bad = {}, 0
  for _, b in ipairs(blocks) do
    if #out >= MAX_CHEATS then break end
    local e = finish(b.lines, b.name, system, #out + 1)
    if e.invalid then bad = bad + 1 end
    out[#out + 1] = e
  end
  return { kind = "txt", cheats = out, bad = bad, dropped = dropped }
end

--- Picks the parser by content.
function I.parse(content, system)
  content = tostring(content or ""):gsub("^\239\187\191", "")
  if content:find("cheat%d+_code") or content:match("^%s*cheats%s*=") or content:find("\ncheats%s*=") then
    return I.parse_cht(content, system)
  end
  return I.parse_txt(content, system)
end

return I

end
__mod["model.library"] = function(...)
-- The cheat list of one game: entries, groups, names, search (pure Lua).
local util = require("model.util")
local formats = require("model.formats")

local L = {}

L.GROUPS = { "db", "mine", "imported" } -- display order
L.MAX_CHEATS = 1000

local counter = 0

--- New unique-enough entry id ([a-z0-9], <= 20 chars).
function L.new_id(clock)
  counter = counter + 1
  return string.format("c%x%03x%04x", (clock or 0) % 0xffffff, counter % 0x1000, math.random(0, 0xffff))
end

--- Entry: { id, name, format, code (lines joined by "\n"), group, enabled, after_reset }
function L.make(fields, clock)
  return {
    id = fields.id or L.new_id(clock),
    name = util.clip(util.trim(fields.name or ""), 60),
    format = fields.format,
    code = fields.code or "",
    group = fields.group or "mine",
    enabled = fields.enabled == true,
    after_reset = fields.after_reset == true or nil,
  }
end

local function key(name) return util.trim(name):lower() end

--- True when another entry (not `except_id`) already has this name.
function L.name_taken(list, name, except_id)
  local k = key(name)
  for _, e in ipairs(list) do
    if e.id ~= except_id and key(e.name) == k then return true end
  end
  return false
end

--- A free name: "Name", else "Name (2)", "Name (3)", ...
function L.unique_name(list, name, taken_extra)
  local function used(n)
    if L.name_taken(list, n) then return true end
    return taken_extra ~= nil and taken_extra[key(n)] == true
  end
  if not used(name) then return name end
  local i = 2
  while used(name .. " (" .. i .. ")") do i = i + 1 end
  return name .. " (" .. i .. ")"
end

function L.find(list, id)
  for i, e in ipairs(list) do if e.id == id then return e, i end end
  return nil
end

function L.matches(entry, query)
  query = util.trim(query or ""):lower()
  if query == "" then return true end
  return entry.name:lower():find(query, 1, true) ~= nil
    or (formats.tags[entry.format] or ""):lower():find(query, 1, true) ~= nil
end

--- Entries per group after the search filter: { db = {...}, mine = {...}, imported = {...} }
function L.groups(list, query)
  local g = { db = {}, mine = {}, imported = {} }
  for _, e in ipairs(list) do
    if L.matches(e, query) then
      local bucket = g[e.group] or g.mine
      bucket[#bucket + 1] = e
    end
  end
  return g
end

--- Number of entries that are on.
function L.on_count(list)
  return util.count(list, function(e) return e.enabled end)
end

return L

end
__mod["model.sync"] = function(...)
-- Persistence in the plugin user store (`uz.store`): key per game, revisions, merge on conflict.
-- Stored value: { v = 1, cheats = { entry... }, deleted = { [id] = true } }
local util = require("model.util")
local formats = require("model.formats")

local S = {}

local MAX_BYTES = 240 * 1024 -- the store accepts 256 KiB
local MAX_TOMBSTONES = 200

--- Store key of a game: cheats.<code|hash|title>; nil when the game cannot be told apart.
function S.key(game)
  game = game or {}
  local id
  if type(game.code) == "string" and game.code ~= "" then
    id = util.slug(game.code, 40)
  elseif type(game.sha256) == "string" and game.sha256 ~= "" then
    id = util.slug(game.sha256, 40)
  elseif type(game.title) == "string" and game.title ~= "" then
    id = util.slug(game.title, 40)
  end
  if not id or id == "" then return nil end
  return "cheats." .. id
end

function S.empty() return { v = 1, cheats = {}, deleted = {} } end

local function clean_entry(e)
  if type(e) ~= "table" or type(e.id) ~= "string" or e.id == "" or #e.id > 40 then return nil end
  if type(e.name) ~= "string" or type(e.code) ~= "string" then return nil end
  if not formats.known(e.format) then return nil end
  local group = e.group
  if group ~= "db" and group ~= "imported" then group = "mine" end
  return { id = e.id, name = util.clip(e.name, 60), format = e.format, code = e.code, group = group,
           enabled = e.enabled == true, after_reset = e.after_reset == true or nil }
end

--- Validates a stored value; anything unusable becomes an empty list.
function S.normalize(v)
  local out = S.empty()
  if type(v) ~= "table" then return out end
  local seen = {}
  for _, e in ipairs(type(v.cheats) == "table" and v.cheats or {}) do
    local c = clean_entry(e)
    if c and not seen[c.id] then
      seen[c.id] = true
      out.cheats[#out.cheats + 1] = c
    end
  end
  if type(v.deleted) == "table" then
    for id, flag in pairs(v.deleted) do
      if type(id) == "string" and flag == true then out.deleted[id] = true end
    end
  end
  return out
end

local function same(a, b)
  return a.name == b.name and a.code == b.code and a.format == b.format and a.group == b.group
end

--- Merges two versions by cheat id. `a` (the local version) wins for the same id; when the other
-- version changed the same cheat differently both stay (the other one as "<name> (2)").
function S.merge(a, b)
  a, b = S.normalize(a), S.normalize(b)
  local out = S.empty()
  for id in pairs(a.deleted) do out.deleted[id] = true end
  for id in pairs(b.deleted) do out.deleted[id] = true end
  local by_id, names = {}, {}
  local function add(e)
    out.cheats[#out.cheats + 1] = e
    by_id[e.id] = e
    names[e.name:lower()] = true
  end
  for _, e in ipairs(a.cheats) do
    if not out.deleted[e.id] then add(e) end
  end
  for _, e in ipairs(b.cheats) do
    if not out.deleted[e.id] then
      local mine = by_id[e.id]
      if not mine then
        add(e)
      elseif not same(mine, e) then
        local copy = util.copy(e)
        copy.id = e.id .. "b"
        copy.enabled = false
        local name = e.name .. " (2)"
        local i = 2
        while names[name:lower()] do i = i + 1; name = e.name .. " (" .. i .. ")" end
        copy.name = name
        if not by_id[copy.id] then add(copy) end
      end
    end
  end
  -- keep the tombstone list short
  local n = 0
  for id in pairs(out.deleted) do
    n = n + 1
    if n > MAX_TOMBSTONES then out.deleted[id] = nil end
  end
  return out
end

--- Reads the stored list. Returns data, revision.
function S.read(store, key)
  local ok, value, rev = pcall(store.get, key)
  if not ok then return S.empty(), nil, value end
  return S.normalize(value), rev
end

local function other_versions(store, key)
  local out = {}
  if type(store.conflicts) ~= "function" then return out end
  local ok, list = pcall(store.conflicts, key)
  if not ok or type(list) ~= "table" then return out end
  for _, item in ipairs(list) do
    if type(item) == "table" then
      out[#out + 1] = (type(item.value) == "table") and item.value or item
    end
  end
  return out
end

--- Writes the list. On conflict both versions are merged and written again (once).
-- Returns data (possibly merged), revision, status ("ok"|"merged"|"failed"|"too_big"), message.
function S.save(store, key, data, rev)
  local doc = { v = 1, cheats = data.cheats, deleted = data.deleted }
  if util.json_size(doc) > MAX_BYTES then return data, rev, "too_big" end
  local ok, res, msg = pcall(store.put, key, doc, rev)
  if not ok then return data, rev, "failed", res end
  if res == true then
    local _, new_rev = store.get(key)
    return data, new_rev or rev, "ok"
  end
  if msg ~= "conflict" then return data, rev, "failed", msg end
  local server, srv_rev = store.get(key)
  local merged = S.merge(data, server)
  for _, v in ipairs(other_versions(store, key)) do merged = S.merge(merged, v) end
  doc = { v = 1, cheats = merged.cheats, deleted = merged.deleted }
  if util.json_size(doc) > MAX_BYTES then return merged, srv_rev, "too_big" end
  local ok2, res2, msg2 = pcall(store.put, key, doc, srv_rev)
  if ok2 and res2 == true then
    local _, new_rev = store.get(key)
    return merged, new_rev or srv_rev, "merged"
  end
  return merged, srv_rev, "failed", ok2 and msg2 or res2
end

return S

end
__mod["model.util"] = function(...)
-- Small helpers shared by the model and the UI (pure Lua, sandbox-safe).
local M = {}

function M.trim(s)
  return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

--- Deep copy of plain data.
function M.copy(v)
  if type(v) ~= "table" then return v end
  local c = {}
  for k, x in pairs(v) do c[k] = M.copy(x) end
  return c
end

--- Lines of a text (CRLF, CR and LF); keeps empty lines so line numbers stay true.
function M.lines(text)
  local out = {}
  text = tostring(text or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
  for line in (text .. "\n"):gmatch("([^\n]*)\n") do out[#out + 1] = line end
  if #out > 0 and out[#out] == "" then out[#out] = nil end
  return out
end

--- Shortens a string to at most n characters (UTF-8 aware) with an ellipsis.
function M.clip(s, n)
  s = tostring(s or "")
  local len = utf8.len(s)
  if not len then return s:sub(1, n) end
  if len <= n then return s end
  return s:sub(1, (utf8.offset(s, n) or (n + 1)) - 1) .. "…"
end

--- Approximate JSON size in bytes of a plain value (for the 256 KiB store limit).
function M.json_size(v)
  local t = type(v)
  if t == "string" then return #v + 2 + select(2, v:gsub('[%c"\\]', "")) end
  if t == "number" or t == "boolean" then return #tostring(v) end
  if t == "table" then
    local n, size = 0, 2
    for k, x in pairs(v) do
      n = n + 1
      size = size + M.json_size(x) + 1
      if type(k) ~= "number" then size = size + #tostring(k) + 3 end
    end
    return size
  end
  return 4
end

--- Lower-case ASCII slug limited to [a-z0-9_-] (store keys: ^[a-z0-9_.-]{1,64}$).
function M.slug(s, max)
  s = tostring(s or ""):lower():gsub("[^a-z0-9_%-]+", "-"):gsub("^%-+", ""):gsub("%-+$", "")
  return s:sub(1, max or 40)
end

--- Counts entries of a list for which fn(entry) is truthy.
function M.count(list, fn)
  local n = 0
  for _, e in ipairs(list) do if fn(e) then n = n + 1 end end
  return n
end

return M

end
__mod["ui.dialog"] = function(...)
-- The add / import dialog, shown as the plugin's `screen` sheet (design 11b-1 to 11b-4, 11c-1, 11c-2).
local formats = require("model.formats")
local util = require("model.util")

local D = {}

local function text(s, style, tone, extra)
  local b = { type = "text", text = s, style = style }
  if tone then b.tone = tone end
  for k, v in pairs(extra or {}) do b[k] = v end
  return b
end

local function fmt_label(t, f) return t("fmt_" .. f) end

--- Error line for the Enter code tab.
local function line_error(t, e)
  local vars = util.copy(e.vars or {})
  vars.n_line = e.n
  return t("line_error", { n = e.n, msg = t(e.key, vars) })
end
D.line_error = line_error

--- "Fix line 2 to add it." / "Fix lines 2 and 3 to add it." (the code field has no line markers)
local function fix_hint(t, errors)
  local nums, seen = {}, {}
  for _, e in ipairs(errors or {}) do
    if e.n and not seen[e.n] then seen[e.n] = true; nums[#nums + 1] = e.n end
  end
  table.sort(nums)
  if #nums == 0 then return t("fix_to_add") end
  if #nums == 1 then return t("fix_line", { lines = nums[1] }) end
  local head = {}
  for i = 1, #nums - 1 do head[i] = tostring(nums[i]) end
  return t("fix_lines", { lines = t("lines_and", { head = table.concat(head, ", "), last = nums[#nums] }) })
end
D.fix_hint = fix_hint

local function enter_page(v)
  local t, dlg = v.t, v.dlg
  local a = v.analysis
  local kids = {}
  kids[#kids + 1] = text(t("lbl_name"), "meta")
  kids[#kids + 1] = { type = "textarea", id = "ta_name", value = dlg.name, lines = 1 }
  if a.name_state == "taken" then kids[#kids + 1] = text(t("name_taken"), "meta", "danger", { id = "name_err" }) end

  local opts = { { value = "auto", label = t("fmt_detect") } }
  for _, f in ipairs(formats.for_system(v.system)) do opts[#opts + 1] = { value = f, label = fmt_label(t, f) } end
  kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = {
    text(t("lbl_format"), "meta"),
    { type = "select", id = "sel_fmt", options = opts, selected = dlg.fmt, action = "fmt" },
  } }
  if dlg.fmt == "auto" then
    kids[#kids + 1] = text(a.detected and t("found_format", { tag = formats.tags[a.detected] }) or t("not_detected"),
      "meta", a.detected and "ok" or nil, { id = "detect" })
  end

  kids[#kids + 1] = text(t("lbl_code"), "meta")
  kids[#kids + 1] = { type = "textarea", id = "ta_code", value = dlg.code, lines = 6, mono = true }

  if a.blank then
    kids[#kids + 1] = text(t("code_hint"), "meta", nil, { id = "status" })
  elseif not a.fmt then
    kids[#kids + 1] = text(t("pick_format_hint"), "meta", "danger", { id = "status" })
  elseif #a.chk.errors == 0 then
    kids[#kids + 1] = text(t("code_ok", { n = a.chk.count, format = fmt_label(t, a.fmt) }), "body", "ok", { id = "status" })
    if a.unsupported then
      kids[#kids + 1] = text(t("fmt_unsupported_note", { core = v.core_name }), "meta", "warning", { id = "unsupported" })
    end
    kids[#kids + 1] = text(t("goes_to_mine"), "meta")
  else
    for i, e in ipairs(a.chk.errors) do
      if i > 8 then
        kids[#kids + 1] = text(t("more_errors", { n = #a.chk.errors - 8 }), "meta", "danger")
        break
      end
      kids[#kids + 1] = text(line_error(t, e), "meta", "danger", { id = "err" .. i })
    end
    if a.chk.other and dlg.fmt ~= "auto" then
      kids[#kids + 1] = text(t("looks_like", { other = fmt_label(t, a.chk.other), chosen = fmt_label(t, a.fmt) }), "meta")
      kids[#kids + 1] = { type = "button", id = "btn_use_fmt", label = t("use_format", { format = fmt_label(t, a.chk.other) }),
        action = "use_fmt", value = a.chk.other, variant = "secondary" }
    end
  end

  kids[#kids + 1] = { type = "toggle", id = "tg_reset", action = "after_reset", label = t("after_reset_label"),
    checked = dlg.after_reset == true }

  local buttons = {}
  if a.ready then
    buttons[#buttons + 1] = { type = "button", id = "btn_confirm", label = dlg.editing and t("save_cheat") or t("add_cheat"),
      action = "confirm_add", variant = "primary" }
  end
  buttons[#buttons + 1] = { type = "button", id = "btn_cancel", label = t("cancel"), action = "dlg_close", variant = "secondary" }
  kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = buttons }
  if not a.ready then
    kids[#kids + 1] = text(a.name_state == "empty" and t("need_name") or fix_hint(t, a.chk and a.chk.errors), "meta", nil, { id = "not_ready" })
  end
  return { type = "column", gap = 8, children = kids }
end

--- Import rows: selectable when the code is valid and the core can use the format.
local function import_state(v, c)
  if c.invalid then return false, v.t("imp_invalid") end
  if not v.supported(c.format) then return false, v.t("not_supported_short") end
  return true
end

local function import_page(v)
  local t, imp = v.t, v.dlg.imp
  local kids = {}
  if not imp then
    kids[#kids + 1] = text(t("imp_hint"), "meta")
    kids[#kids + 1] = { type = "button", id = "btn_pick", label = t("choose_file"), action = "pick_file", variant = "primary" }
    return { type = "column", gap = 8, children = kids }
  end
  if imp.error then
    kids[#kids + 1] = { type = "empty", id = "imp_error", title = t("imp_error_title"), text = imp.error, tone = "danger",
      action_label = t("choose_file"), action = "pick_file" }
    return { type = "column", gap = 8, children = kids }
  end
  local cheats = imp.cheats
  local usable, selected = 0, 0
  for i, c in ipairs(cheats) do
    if import_state(v, c) then
      usable = usable + 1
      if imp.selected[i] then selected = selected + 1 end
    end
  end
  kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = {
    text(t("file_line", { name = imp.name or "", kb = math.max(1, math.floor((imp.size or 0) / 1024 + 0.5)) }), "meta", nil, { id = "file_line" }),
    { type = "button", id = "btn_pick", label = t("choose_another"), action = "pick_file", variant = "quiet" },
  } }
  if #cheats == 0 then
    kids[#kids + 1] = { type = "empty", id = "imp_none", title = t("imp_none_title"), text = t("imp_hint") }
    if (imp.dropped or 0) > 0 then
      kids[#kids + 1] = text(t(imp.dropped == 1 and "dropped_one" or "dropped_n", { n = imp.dropped }), "meta", "warning", { id = "dropped" })
    end
    return { type = "column", gap = 8, children = kids }
  end
  kids[#kids + 1] = text(t("found_n", { found = #cheats, usable = usable, core = v.core_name }), "body", nil, { id = "found" })
  if (imp.dropped or 0) > 0 then
    kids[#kids + 1] = text(t(imp.dropped == 1 and "dropped_one" or "dropped_n", { n = imp.dropped }), "meta", "warning", { id = "dropped" })
  end
  if usable > 0 then
    kids[#kids + 1] = { type = "toggle", id = "tg_all", action = "imp_all", label = t("imp_all", { n = usable }),
      checked = selected == usable }
  end
  local shown = math.min(#cheats, imp.shown or 40)
  for i = 1, shown do
    local c = cheats[i]
    local ok, why = import_state(v, c)
    local children = {}
    if ok then
      children[#children + 1] = { type = "toggle", id = "it" .. i, action = "imp:" .. i, checked = imp.selected[i] == true }
    else
      children[#children + 1] = { type = "toggle", id = "it" .. i, action = "imp:" .. i, checked = false, disabled = true }
    end
    local name = text(c.name, "body", nil, { wrap = true })
    if why then
      name = { type = "column", gap = 4, children = { name, text(why, "meta", "warning") } }
    end
    children[#children + 1] = name
    children[#children + 1] = { type = "badge", text = formats.tags[c.format] or "?" }
    kids[#kids + 1] = { type = "row", id = "irow" .. i, gap = 8, align = "center", children = children }
  end
  if #cheats > shown then
    kids[#kids + 1] = { type = "button", id = "btn_imp_more", label = t("and_n_more", { n = #cheats - shown }),
      action = "imp_more", variant = "quiet" }
  end
  if selected > 0 then
    local dup = 0
    local seen = {}
    for _, e in ipairs(v.list) do seen[e.name:lower()] = true end
    for i, c in ipairs(cheats) do
      if imp.selected[i] and seen[c.name:lower()] then dup = dup + 1 end
    end
    if dup > 0 then
      kids[#kids + 1] = text(t(dup == 1 and "names_exist_one" or "names_exist", { n = dup }), "meta", "warning", { id = "dups" })
      kids[#kids + 1] = text(t("keep_both"), "meta")
    end
    kids[#kids + 1] = { type = "button", id = "btn_import", label = t(selected == 1 and "import_one" or "import_n", { n = selected }), action = "import_go",
      variant = "primary" }
  end
  return { type = "column", gap = 8, children = kids }
end

--- Why the database gave nothing: classify the message of uz.cheats.database().
function D.db_problem(msg)
  msg = tostring(msg or "")
  if msg == "off" or msg == "offline" then return msg, nil end
  if msg == "loading" or msg == "error: loading" then return "loading", nil end
  if msg == "not_found" then return "none", nil end
  if msg == "unavailable" then return "unavailable", nil end -- on, but no lists yet (not loaded or last update failed)
  return "error", (msg:gsub("^error:%s*", ""))
end

local function db_page(v)
  local t, db = v.t, v.dlg.db
  local kids = {}
  if not db or db.problem == "loading" then
    kids[#kids + 1] = text(t("db_looking", { game = v.game_title }), "meta", nil, { id = "db_looking" })
    return { type = "column", gap = 8, children = kids }
  end
  if db.problem then
    local key = db.problem
    local body
    if key == "error" then body = util.clip(db.message or "", 200) end
    local e = { type = "empty", id = "db_problem", title = t("db_" .. key .. "_title"),
      text = body or t("db_" .. key .. "_text"), tone = key == "error" and "danger" or key == "unavailable" and "warning" or nil }
    if key ~= "off" then e.action_label, e.action = t("db_retry"), "db_retry" end -- turning it on is the admin's job
    kids[#kids + 1] = e
    return { type = "column", gap = 8, children = kids }
  end
  kids[#kids + 1] = text(t("db_matched", { game = v.game_title, system = tostring(v.system or ""):upper() }), "eyebrow")
  if db.source then
    kids[#kids + 1] = text(t("db_source", { source = util.clip(tostring(db.source), 60),
      date = util.clip(tostring(db.updated_at or "?"), 24) }), "meta", nil, { id = "db_source" })
  end
  local rows, visible, addable = {}, 0, 0
  local q = util.trim(db.query or ""):lower()
  for i, c in ipairs(db.cheats) do
    local tag = formats.tags[c.format] or "?"
    local added = db.added[i] == true
    local ok = c.format ~= nil and v.supported(c.format)
    if not added and ok then addable = addable + 1 end
    if q == "" or c.name:lower():find(q, 1, true) then
      visible = visible + 1
      if visible <= (db.shown or 50) then
        local kids_row = { text(c.name, "body", nil, { wrap = true }), { type = "badge", text = tag } }
        if added then
          kids_row[#kids_row + 1] = { type = "badge", text = t("db_added"), tone = "ok" }
        elseif not ok then
          kids_row[#kids_row + 1] = text(t("not_supported_short"), "meta", "warning")
        else
          kids_row[#kids_row + 1] = { type = "button", id = "btn_d" .. i, label = t("db_add"), action = "db_add", value = i,
            variant = "secondary" }
        end
        rows[#rows + 1] = { type = "row", id = "d" .. i, gap = 8, align = "center", children = kids_row }
      end
    end
  end
  -- Add all and the search stay above the rows
  if addable > 0 then
    kids[#kids + 1] = { type = "button", id = "btn_db_all", label = t("db_add_all", { n = addable }),
      action = "db_add_all", variant = "primary" }
  end
  kids[#kids + 1] = { type = "textfield", id = "db_search", action = "db_search", live = true, text = db.query or "",
    placeholder = t("search_placeholder") }
  if visible == 0 then
    kids[#kids + 1] = { type = "empty", id = "db_nomatch", title = t("no_match", { query = db.query or "" }),
      action_label = t("clear_search"), action = "db_search_clear" }
  else
    kids[#kids + 1] = { type = "column", id = "db_list", gap = 6, children = rows }
  end
  if visible > (db.shown or 50) then
    kids[#kids + 1] = { type = "button", id = "btn_db_more", label = t("show_more", { n = visible - (db.shown or 50) }),
      action = "db_more", variant = "secondary" }
  end
  kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = {
    { type = "button", id = "btn_close", label = t("close"), action = "dlg_close", variant = "quiet" } } }
  return { type = "column", gap = 8, children = kids }
end

--- v = { t, dlg, system, game_title, core_name, supported(fmt), list }
function D.build(v)
  local t, dlg = v.t, v.dlg
  local head = {
    text(t("dlg_eyebrow", { system = tostring(v.system or ""):upper() }), "eyebrow"),
    text(dlg.editing and t("dlg_edit_title", { game = v.game_title }) or t("dlg_title", { game = v.game_title }), "title"),
  }
  if dlg.done then
    head[#head + 1] = text(dlg.done, "body", "ok", { id = "done" })
    head[#head + 1] = { type = "row", gap = 8, align = "center", children = {
      { type = "button", id = "btn_again", label = t("add_more"), action = "dlg_again", variant = "secondary" },
      { type = "button", id = "btn_close", label = t("close"), action = "dlg_close", variant = "primary" },
    } }
    return { type = "column", gap = 12, width = "dialog", children = head }
  end
  if dlg.editing then
    head[#head + 1] = enter_page(v)
    return { type = "column", gap = 12, width = "dialog", children = head }
  end
  local tabs = { t("tab_enter"), t("tab_import"), t("tab_database") }
  local empty = { type = "column", children = {} }
  local pages = { empty, empty, empty }
  if dlg.tab == 1 then pages[1] = enter_page(v)
  elseif dlg.tab == 2 then pages[2] = import_page(v)
  else pages[3] = db_page(v) end
  head[#head + 1] = { type = "tabs", id = "dlg_tabs", tabs = tabs, selected = dlg.tab, action = "dlg_tab", children = pages }
  return { type = "column", gap = 12, width = "dialog", children = head }
end

return D

end
__mod["ui.panel"] = function(...)
-- The Cheats tab in the game's side panel (design 11a-1, 11a-2, 11a-3).
local formats = require("model.formats")
local library = require("model.library")

local P = {}

local GROUP_KEYS = { db = "group_db", mine = "group_mine", imported = "group_imported" }

local function text(s, style, tone, extra)
  local b = { type = "text", text = s, style = style }
  if tone then b.tone = tone end
  for k, v in pairs(extra or {}) do b[k] = v end
  return b
end

local function entry_row(v, e)
  local t = v.t
  local supported = v.supported(e.format)
  local meta, meta_tone
  if not supported then
    meta, meta_tone = t("not_supported", { core = v.core_name }), "warning"
  elseif v.rejected[e.id] then
    meta, meta_tone = t("rejected", { reason = v.rejected[e.id] }), "danger"
  elseif e.enabled and e.after_reset then
    meta = t("after_reset_hint")
  end
  local name = text(e.name, "body", nil, { wrap = true })
  local left = name
  if meta then
    left = { type = "column", gap = 4, children = { name, text(meta, "meta", meta_tone) } }
  end
  local children = { left, { type = "badge", text = formats.tags[e.format] or "?" } }
  if e.after_reset then children[#children + 1] = { type = "badge", text = t("tag_after_reset"), tone = "info" } end
  if v.edit then
    children[#children + 1] = { type = "button", label = t("edit"), action = "edit:" .. e.id, variant = "quiet" }
    children[#children + 1] = { type = "button", label = t("remove"), action = "remove:" .. e.id, variant = "danger",
      confirm = { title = t("remove_title", { name = e.name }), text = t("remove_text"),
                  confirm_label = t("remove"), danger = true } }
  elseif v.blocked or not supported then
    children[#children + 1] = { type = "toggle", id = "tg_" .. e.id, action = "toggle:" .. e.id, checked = false,
      disabled = true }
  else
    children[#children + 1] = { type = "toggle", id = "tg_" .. e.id, action = "toggle:" .. e.id, checked = e.enabled }
  end
  return { type = "row", id = "row_" .. e.id, gap = 8, align = "center", children = children }
end

local function group_section(v, g, list)
  local t = v.t
  local limit = v.limits[g] or v.page
  local rows = {}
  for i = 1, math.min(#list, limit) do rows[#rows + 1] = entry_row(v, list[i]) end
  if #list > limit then
    rows[#rows + 1] = { type = "button", label = t("show_more", { n = #list - limit }), action = "more:" .. g,
                        variant = "quiet" }
  end
  return { type = "section", id = "grp_" .. g, title = t(GROUP_KEYS[g]) .. " · " .. #list, children = rows }
end

--- v: { t, game_title, on_count, blocked, supported(fmt), core_name, rejected, edit, query, groups, total,
---      limits, page, state ("ok"|"no_game"|"unavailable"), note }
function P.build(v)
  local t = v.t
  if v.state == "unavailable" then
    return { type = "column", gap = 12, children = {
      { type = "empty", title = t("unavailable_title"), text = t("unavailable_text"), tone = "warning" } } }
  elseif v.state == "no_game" then
    return { type = "column", gap = 12, children = {
      { type = "empty", title = t("no_game_title"), text = t("no_game_text") } } }
  end

  local header = { text(t("tab_eyebrow"), "eyebrow") }
  if v.blocked then
    header[#header + 1] = { type = "badge", text = t("off_in_run"), tone = "warning" }
  else
    header[#header + 1] = { type = "badge", text = t("n_on", { n = v.on_count }), tone = v.on_count > 0 and "ok" or "neutral" }
  end
  local kids = { { type = "row", gap = 8, align = "center", children = header } }

  if v.awaiting and not v.blocked then
    kids[#kids + 1] = text(t("consent_waiting"), "meta", nil, { id = "waiting" })
  end

  if v.blocked then
    kids[#kids + 1] = { type = "card", id = "blocked", eyebrow = t("blocked_title"), children = {
      text(t("blocked_text"), "meta"),
      { type = "button", id = "btn_recheck", label = t("check_again"), action = "recheck", variant = "quiet" } } }
  end

  kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = {
    { type = "button", id = "btn_add", label = t("add_cheat"), action = "add", variant = "primary" },
    { type = "button", id = "btn_db", label = t("cheat_database"), action = "open_db", variant = "secondary" },
  } }

  if v.total == 0 then
    kids[#kids + 1] = { type = "empty", id = "empty_none", title = t("empty_title", { game = v.game_title }),
      text = t("empty_text") }
  else
    kids[#kids + 1] = { type = "textfield", id = "search", action = "search", live = true, text = v.query,
      placeholder = t("search_placeholder") }
    local tools = { { type = "chip", id = "chip_edit", text = t("edit_list"), action = "edit_mode", selected = v.edit } }
    if v.on_count > 0 and not v.blocked then
      tools[#tools + 1] = { type = "chip", id = "chip_all_off", text = t("turn_all_off"), action = "all_off" }
    end
    kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = tools }
    local shown = 0
    for _, g in ipairs(library.GROUPS) do
      local list = v.groups[g]
      if #list > 0 then
        shown = shown + #list
        kids[#kids + 1] = group_section(v, g, list)
      end
    end
    if shown == 0 then
      kids[#kids + 1] = { type = "empty", id = "empty_match", title = t("no_match", { query = v.query }),
        action_label = t("clear_search"), action = "search_clear" }
    end
  end

  if v.note then kids[#kids + 1] = text(v.note, "meta", "warning", { id = "note" }) end
  return { type = "column", gap = 12, children = kids }
end

return P

end
require("main")
